#!/usr/bin/env bash
# verdict-lookup.sh — the verdict layer's query, index generator, and lint.
#
# Deployed verbatim by /deep-thinking:init-vault and used by /deep-thinking:verdict
# and /deep-thinking:ground (Stage 1.0). DO NOT EDIT THIS FILE IN A VAULT — it is a
# plugin artifact; fix it in the plugin and redeploy, exactly as with fts5-reindex.py.
#
# Why a query and not a read: the cost of reading a hub is paid on every question,
# while the cost of a query is proportional to its result. Reading the router (~5 KB)
# and calling this script locates a card without opening a domain index.
#
# Why it filters by path and not by tag: the FTS5 schema has no `tags` column. Only
# `description` and `body` are indexed, so MATCH 'verdict' also returns every
# unrelated document whose prose happens to contain the word (measured: 94 hits for
# 59 cards). A path predicate on the UNINDEXED `rel_path` column is exact and free.
# UNINDEXED means "not full-text searchable", not "unusable in WHERE" — `=` and
# `instr()` work normally, while `LIKE` silently returns zero rows against these
# columns. Never LIKE.
#
# usage: ./verdict-lookup.sh <keyword> [keyword2 ...]   # OR-combined
#        ./verdict-lookup.sh --all                      # every card + expiry
#        ./verdict-lookup.sh --expired                  # expired cards only
#        ./verdict-lookup.sh --emit-index [domain]      # regenerate domain INDEX.md
#        ./verdict-lookup.sh --lint                     # layer hygiene (exit 1 on violations)
#
# --emit-index generates the domain listing FROM CARD FRONTMATTER. A hand-maintained
# index writes every ruling twice; measured on one vault it grew to 99 KB, ranked last
# in BM25 on every query it matched, cost 63 hand edits across 200 commits, and still
# advertised a table its owning card had transferred away six days earlier. Derived
# state cannot drift. Do not hand-edit a generated index.
#
# --lint exists because of a measurement: on a 178-card vault, every rule with a
# machine behind it held (stale_after coverage 100%, generated-index drift 0, type
# contract violations 0) and every rule that existed only as prose had decayed
# (ceiling 56% breach, mandatory slots ~31% missing). Writing the rule more forcefully
# does not close that gap. This is the observer.
set -euo pipefail

# --- Locate the index, including from a git worktree --------------------------
# The DB is gitignored, so a worktree checkout will not have one. Fall back to the
# main checkout's index rather than failing.
# Resolved lazily: --emit-index and --lint read the files themselves and must work on
# a vault that has not been indexed yet.
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
db=""
resolve_db() {
  [[ -n "$db" ]] && return 0
  db="$here/vault.fts5.db"
  [[ -f "$db" ]] && return 0
  local common
  common="$(git -C "$here" rev-parse --path-format=absolute --git-common-dir 2>/dev/null || true)"
  if [[ -n "$common" && -f "$(dirname "$common")/vault.fts5.db" ]]; then
    db="$(dirname "$common")/vault.fts5.db"
    echo "[i] no local index — using the main checkout's: $db" >&2
    echo "[i] edits in this worktree are not reflected. Run ./reindex.sh if needed." >&2
  else
    echo "[FATAL] vault.fts5.db not found. Run ./reindex.sh first." >&2
    exit 1
  fi
}

today="$(date +%F)"

# --- Card roots ---------------------------------------------------------------
# A vault may keep more than one card root: a public `verdicts/` plus scoped roots
# such as `<scope>/verdicts/`. A predicate anchored to one root silently drops the
# others and answers as though no card owned the question — the most expensive
# failure this layer has, because it is invisible. Discover every root, then OR them.
mapfile -t CARD_ROOTS < <(
  { [[ -d "$here/verdicts" ]] && echo "verdicts/"
    find "$here" -mindepth 2 -maxdepth 2 -type d -name verdicts -not -path '*/.*' 2>/dev/null \
      | sed "s|^$here/||;s|$|/|"
  } | sort -u
)
[[ ${#CARD_ROOTS[@]} -eq 0 ]] && { echo "[FATAL] no verdicts/ root found under $here" >&2; exit 1; }

pred=""
for r in "${CARD_ROOTS[@]}"; do
  pred+="${pred:+ OR }instr(rel_path,'$r')=1"
done
pred="($pred)"

emit() {
  resolve_db
  sqlite3 "$db" -separator $'\t' "$1" | awk -F'\t' -v today="$today" '
    {
      flag = ($3 != "" && $3 < today) ? "EXPIRED" : "live"
      printf "%-8s %-10s %s\n         %s\n", flag, $3, $1, $2
    }
    END { if (NR == 0) print "(0 rows — no card owns this. Investigate, then mint one with /verdict.)" }'
}

case "${1:-}" in
  --all)
    emit "SELECT rel_path, description, stale_after FROM notes_fts
          WHERE $pred AND description != '' AND stale_after != ''
          ORDER BY stale_after;"
    exit 0 ;;
  --expired)
    emit "SELECT rel_path, description, stale_after FROM notes_fts
          WHERE $pred AND description != '' AND stale_after != ''
            AND stale_after < '$today'
          ORDER BY stale_after;"
    exit 0 ;;
  --emit-index)
    python3 - "$here" "${2:-}" <<'PY'
import sys, re, pathlib, datetime, collections

import os

root, only = pathlib.Path(sys.argv[1]), (sys.argv[2] or None)
today = datetime.date.today().isoformat()

# The generated index is boilerplate around card-derived values, so a vault written
# in another language should not have its indexes flipped to English on regeneration.
# Set VERDICT_INDEX_LANG in the vault (e.g. via .envrc) to localise the boilerplate.
T = {
  "en": dict(
    desc="Generated listing of the {n} verdict cards in {d} — path, ruling, expiry. Not hand-edited",
    title="{d} — verdict cards",
    warn1="> 🔴 **Generated file. Do not edit** — the next `--emit-index` run overwrites it.",
    warn2="> Every value here is derived from card frontmatter, so it cannot disagree with the cards.",
    warn3="> Regenerate: `./verdict-lookup.sh --emit-index {d}` · Find by keyword: `./verdict-lookup.sh <keyword>`",
    count="{n} cards", expired=" · **{e} expired**", clean=" · none expired", gen=" · generated {t}",
    head="| Card | The question it closes (= the ruling) | Expiry |"),
  "ko": dict(
    desc="{d} 도메인 결론 카드 {n}장의 생성 목록 — 경로·결론·만료. 손으로 고치지 않는다",
    title="{d} — 결론 카드 목록",
    warn1="> 🔴 **이 파일은 생성물이다. 직접 편집하지 말 것** — 다음 `--emit-index` 실행에서 덮어써진다.",
    warn2="> 내용은 각 카드의 프론트매터에서 파생되므로 카드와 어긋날 수 없다. 고칠 곳은 **카드**다.",
    warn3="> 재생성: `./verdict-lookup.sh --emit-index {d}` · 키워드로 찾기: `./verdict-lookup.sh <키워드>`",
    count="카드 {n}장", expired=" · **만료 {e}장**", clean=" · 만료 없음", gen=" · 생성 {t}",
    head="| 카드 | 이 카드가 닫는 질문 (= 결론) | 만료 |"),
}
L = T.get(os.environ.get("VERDICT_INDEX_LANG", "en"), T["en"])

# Same root discovery as the shell side: verdicts/ plus any <scope>/verdicts/.
bases = [root / "verdicts"] + sorted(
    d for d in root.glob("*/verdicts") if d.is_dir() and not d.parts[-2].startswith("."))
bases = [b for b in bases if b.is_dir()]

def fm(text):
    m = re.match(r"\A---\n(.*?)\n---\n", text, re.S)
    if not m: return {}
    out = {}
    for line in m.group(1).splitlines():
        k = re.match(r"^([a-z_]+):\s*(.*)$", line)
        if k: out[k.group(1)] = k.group(2).strip().strip("\"'")
    return out

# Index spots = directories that already have an INDEX.md, plus card-bearing
# directories directly under a root. Preserves an existing nested topology.
def has_card(d):
    return any(p.name not in ("INDEX.md", "CHARTER.md") for p in d.rglob("*.md"))

spots = set()
for base in bases:
    spots |= {p.parent for p in base.rglob("INDEX.md")}
    spots |= {d for d in base.iterdir() if d.is_dir() and has_card(d)}

def base_of(d):
    return next(b for b in bases if b == d or b in d.parents)

def label(base, spot):
    name = spot.relative_to(base).as_posix()
    prefix = base.relative_to(root).as_posix()          # "verdicts" or "<scope>/verdicts"
    return name if prefix == "verdicts" else f"{prefix.rsplit('/verdicts',1)[0]}/{name}"

domains, home = collections.defaultdict(list), {}
for spot in spots:
    base = base_of(spot)
    name = label(base, spot)
    if only and name != only and spot.name != only: continue
    home[name] = spot
    nested = {s for s in spots if s != spot and spot in s.parents}
    for p in sorted(spot.rglob("*.md")):
        if p.name in ("INDEX.md", "CHARTER.md"): continue
        if any(n in p.parents for n in nested): continue   # a child INDEX owns it
        domains[name].append((p, fm(p.read_text(errors="ignore"))))

if not domains:
    print(f"[!] no matching domain{f' ({only})' if only else ''}.", file=sys.stderr); sys.exit(1)

for d, cards in sorted(domains.items()):
    idx = home[d] / "INDEX.md"
    cards.sort(key=lambda c: (c[1].get("stale_after") or "9999", c[0].name))
    exp = [c for c in cards if (c[1].get("stale_after") or "9999") < today]
    lines = [
        "---", "type: index",
        'description: "' + L["desc"].format(n=len(cards), d=d) + '"',
        f"timestamp: {today}", "status: stable", "generated_by: verdict-lookup.sh --emit-index",
        "---", "",
        "# " + L["title"].format(d=d), "",
        L["warn1"], L["warn2"], L["warn3"].format(d=d), "",
        L["count"].format(n=len(cards))
        + (L["expired"].format(e=len(exp)) if exp else L["clean"])
        + L["gen"].format(t=today), "",
        L["head"], "|---|---|---|",
    ]
    for p, f in cards:
        rel = p.relative_to(home[d]).as_posix()
        sa = f.get("stale_after", "")
        mark = "⚠️ " if sa and sa < today else ""
        desc = (f.get("description") or "").replace("|", "\\|")
        lines.append(f"| [{p.stem}]({rel}) | {desc} | {mark}{sa or '—'} |")
    lines.append("")
    idx.write_text("\n".join(lines))
    print(f"[OK] {idx.relative_to(root)} — {len(cards)} cards, {len(idx.read_text().encode())/1024:.1f} KB")
PY
    exit 0 ;;
  --lint)
    python3 - "$here" <<'PY'
import sys, re, pathlib, datetime

root = pathlib.Path(sys.argv[1])
today = datetime.date.today().isoformat()

# --- Thresholds (rationale lives in the verdict skill) ------------------------
CEILING      = 15 * 1024   # one card. Over it, split along the four axes
ROUTER_MAX   = 12 * 1024   # verdicts.md is charged to every question, so it is tighter
ROUTER_ROW   = 160         # one domain row. A row that became a paragraph is a mirrored ruling
DOMAIN_CARDS = 20          # per domain. Over it, cut into subdomains
DOMAIN_BYTES = 300 * 1024

MARKERS = re.compile(r"🆕|🔄|✏️|\bupdated\b|\bnew!\b|\(new\)|addendum|as of this session")
# A section titled with a date is the same violation as an inline edit marker, one
# level up: it is where a card stops being state and becomes a log.
DATE_HEAD = re.compile(r"^#{2,4}\s+\W{0,4}(20\d\d[-.]\s?)?\d{1,2}[-./]\d{1,2}\b")

bases = [root / "verdicts"] + sorted(
    d for d in root.glob("*/verdicts") if d.is_dir() and not d.parts[-2].startswith("."))
bases = [b for b in bases if b.is_dir()]
files = sorted(p for b in bases for p in b.rglob("*.md"))

def fm(t):
    m = re.match(r"\A---\n(.*?)\n---\n", t, re.S)
    return dict(re.findall(r"^([a-z_]+):\s*(.*)$", m.group(1), re.M)) if m else {}

cards, aliens, viol = [], [], {}
for p in files:
    if p.name == "CHARTER.md":
        continue
    txt = p.read_text(errors="ignore")
    t = fm(txt).get("type", "").strip().strip("\"'")
    rel = p.relative_to(root).as_posix()
    if t == "index":
        continue
    if t != "canon":
        aliens.append((len(txt.encode()), rel, t or "?"))
        continue
    cards.append((rel, txt, len(txt.encode())))

def report(key, title, rows, unit="", top=6):
    if not rows:
        print(f"  OK  {title}")
        return
    viol[key] = len(rows)
    print(f"  !!  {title} — {len(rows)}")
    for n, lbl in rows[:top]:
        print(f"        {n:>6}{unit}  {lbl}")
    if len(rows) > top:
        print(f"        … and {len(rows)-top} more")

total = sum(c[2] for c in cards)
print(f"\n=== verdict layer lint · {today} ===")
print(f"{len(cards)} cards / {total/1024:.0f} KB  (mean {total/max(len(cards),1)/1024:.1f} KB)"
      f"  · roots: {', '.join(b.relative_to(root).as_posix() for b in bases)}\n")

print("[1] Ceiling — 15 KB per card. Asked after every amendment, not only at mint")
report("ceiling", f"over {CEILING//1024} KB",
       sorted(((s // 1024, r) for r, _, s in cards if s > CEILING), reverse=True), " KB")

print("\n[2] Markers — the card is state, git is the log")
report("markers", "files carrying edit markers",
       sorted(((len(MARKERS.findall(t)), r) for r, t, _ in cards if MARKERS.search(t)), reverse=True))

print("\n[3] Chronology — headings name decisions and subjects, never dates or events")
report("chronology", "files with dated section headings",
       sorted(((sum(bool(DATE_HEAD.match(l)) for l in t.splitlines()), r)
               for r, t, _ in cards if any(DATE_HEAD.match(l) for l in t.splitlines())), reverse=True))

print("\n[4] Slots — Rejects is the highest value per token; Appeal is what makes brevity safe")
# A slot is identified by its FUNCTION, not by an English label. Vaults localise these
# headings and number them ("## 3. 탈락 (Rejects) — …"), so matching the English word
# alone reports a slot as missing when it is present — the most misleading kind of
# lint failure, because it sends a session to rewrite a card that was already correct.
# Extend SLOTS when a vault settles on another wording; do not rename its cards.
SLOTS = {
    "Rejects": r"Rejects|탈락|却下",
    "Appeal":  r"Appeal|재조사|뒤집히는\s*조건|覆",
}
for slot, alts in SLOTS.items():
    pat = rf"^#{{2,3}}\s*(?:\d+[.)]\s*)?[^\n]*(?:{alts})"
    miss = [r for r, t, _ in cards if not re.search(pat, t, re.M)]
    if miss:
        viol[slot] = len(miss)
        print(f"  !!  no {slot} — {len(miss)} of {len(cards)} ({len(miss)*100//max(len(cards),1)}%)")
        for r in miss[:4]:
            print(f"        {r}")
        if len(miss) > 4:
            print(f"        … and {len(miss)-4} more")
    else:
        print(f"  OK  every card has {slot}")

print("\n[5] Admission — a card root holds type: canon cards and generated INDEX.md, nothing else")
report("admission", "non-card files", sorted(((s // 1024, f"{r}  ({t})") for s, r, t in aliens), reverse=True), " KB")

print("\n[6] Domains — an oversized domain is what turns a router row into a paragraph")
dom = {}
for r, _, s in cards:
    d = "/".join(r.split("/")[:-1])
    n, b = dom.get(d, (0, 0))
    dom[d] = (n + 1, b + s)
report("domains", f"over {DOMAIN_CARDS} cards or {DOMAIN_BYTES//1024} KB",
       sorted(((n, f"{d}  {b//1024} KB") for d, (n, b) in dom.items()
               if n > DOMAIN_CARDS or b > DOMAIN_BYTES), reverse=True), " cards")

print("\n[7] Router — charged to every question. One row per domain, no rulings, no queues")
hub = root / "verdicts.md"
if hub.is_file():
    ht = hub.read_text(errors="ignore"); hb = len(ht.encode()); ok = True
    if hb > ROUTER_MAX:
        print(f"  !!  {hb/1024:.1f} KB > {ROUTER_MAX//1024} KB — compress the rows or split"); ok = False
    # Measure the description cell, not the whole line: link markup is fixed overhead
    # that a long domain name inflates, and it is not what grows when a ruling leaks in.
    rows = [l for l in ht.splitlines() if re.match(r"^\|\s*\[", l)]
    def cell(l):
        c = [x.strip() for x in l.strip().strip("|").split("|")]
        return c[1] if len(c) > 1 else ""
    long = sorted(((len(cell(l)), re.search(r"\[([^\]]+)\]", l).group(1)) for l in rows
                   if len(cell(l)) > ROUTER_ROW), reverse=True)
    if long:
        print(f"  !!  {len(long)} description cells over {ROUTER_ROW} chars — a ruling in the router is a mirror"); ok = False
        for n, d in long[:5]:
            print(f"        {n:>6}  {d}")
    if MARKERS.search(ht):
        print(f"  !!  {len(MARKERS.findall(ht))} edit markers — the router is state too"); ok = False
    wip = [l for l in ht.splitlines() if re.match(r"^##\s", l) and re.search(r"(?i)queue|pending|todo|backlog|not yet", l)]
    if wip:
        print(f"  !!  {len(wip)} work-in-progress section(s) — move out of the hot path: {wip[0].strip()}"); ok = False
    if ok:
        print(f"  OK  {hb/1024:.1f} KB · longest row {max((len(l) for l in rows), default=0)} chars · no markers")
    else:
        viol["router"] = 1
else:
    print("  --  no verdicts.md router yet")

print("\n" + "=" * 60)
if viol:
    print("!! violations: " + " · ".join(f"{k} {v}" for k, v in viol.items()))
    print("   order of repair: [5] admission → [1] ceiling + [3] chronology → [7] router → [4] slots → [2] markers")
    sys.exit(1)
print("OK — no violations")
PY
    exit 0 ;;
  "")
    echo "usage: $0 <keyword> [keyword2 ...] | --all | --expired | --emit-index [domain] | --lint" >&2
    exit 2 ;;
esac

# --- Warn on sub-3-character terms --------------------------------------------
# The trigram tokenizer does not index tokens shorter than three characters. In CJK
# that is an ordinary class of word, and it fails silently rather than erroring —
# the single largest cause of a misleading zero-row result.
for kw in "$@"; do
  if [[ $(printf '%s' "$kw" | wc -m) -lt 3 ]]; then
    echo "[!] '$kw' is under 3 characters — not indexed by the trigram tokenizer, so this term is ignored. Use a longer compound." >&2
  fi
done

# Combine keywords into an FTS5 OR expression. Terms containing spaces or hyphens
# MUST be quoted, or the tokenizer reads the second token as a column name.
match=""
for kw in "$@"; do
  esc="${kw//\"/\"\"}"
  match+="${match:+ OR }\"$esc\""
done

emit "SELECT DISTINCT f.rel_path, f.description, f.stale_after
      FROM notes_fts f
      WHERE f.rel_path IN (
              SELECT rel_path FROM notes_fts
              WHERE notes_fts MATCH '$match' AND $pred
            )
        AND f.description != '' AND f.stale_after != ''
      ORDER BY f.stale_after;"
